package pe.clinica.cardenas.labservice.config; import lombok.RequiredArgsConstructor; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile; import pe.clinica.cardenas.labservice.domain.LabOrder; import pe.clinica.cardenas.labservice.repository.LabOrderRepository; import java.math.BigDecimal; import java.time.LocalDate;
@Configuration @Profile("local") @RequiredArgsConstructor public class LocalDataInitializer{private final LabOrderRepository orders; @Bean CommandLineRunner seedLab(){return args->{if(orders.count()==0){orders.save(LabOrder.builder().patientName("Andrea Flores Mendoza").doctorName("Dra. Valeria Cárdenas").laboratory("Laboratorio dental externo").workType("Corona de zirconio").toothPieces("16").material("Zirconio").shade("A2").sentDate(LocalDate.now().minusDays(3)).expectedDate(LocalDate.now().plusDays(4)).cost(new BigDecimal("480.00")).notes("Adjuntar escaneo intraoral").labStatus("EN FABRICACIÓN").build()); orders.save(LabOrder.builder().patientName("Sofía Torres Díaz").doctorName("Dra. Valeria Cárdenas").laboratory("OrthoLab Sur").workType("Retenedor removible").toothPieces("Arcada superior").material("Acrílico").shade("Transparente").sentDate(LocalDate.now().minusDays(5)).expectedDate(LocalDate.now().plusDays(1)).cost(new BigDecimal("220.00")).notes("Validar ajuste antes de entrega").labStatus("LISTO PARA ENTREGA").build());}};}}
